g=grid
H,W=len(g),len(g[0])
anom={2,9}
# find bboxes of solid blocks (colors != 3, not anom), via connected components
seen=[[False]*W for _ in range(H)]
boxes=[]
for i in range(H):
    for j in range(W):
        if g[i][j] not in anom and g[i][j]!=3 and not seen[i][j]:
            col=g[i][j]; st=[(i,j)]; comp=[]
            seen[i][j]=True
            while st:
                a,b=st.pop(); comp.append((a,b))
                for a2,b2 in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0<=a2<H and 0<=b2<W and not seen[a2][b2] and g[a2][b2]==col:
                        seen[a2][b2]=True; st.append((a2,b2))
            rs=[c[0] for c in comp]; cs=[c[1] for c in comp]
            boxes.append((min(rs),max(rs),min(cs),max(cs),col))
out=[r[:] for r in g]
for i in range(H):
    for j in range(W):
        if g[i][j] in anom:
            for r0,r1,c0,c1,col in boxes:
                if r0<=i<=r1 and c0<=j<=c1:
                    out[i][j]=col; break
            else:
                out[i][j]=3
for r in out: print(' '.join(map(str,r)))
print([b for b in boxes])
